"""Apply the documented reply to working evidence only, never archived r2.

Run after collection/inspection. Immutable publisher snapshots are not rewritten.
This overlay keeps yt-dlp component rows and every source gate unchanged.
"""
import hashlib, json, pathlib, re
from inspect_inputs import NAMES

OUT = pathlib.Path(__file__).resolve().parent
INVENTORY_DIR = OUT.parent/'source-taskbar-20261009'
REQUEST_DIR = OUT.parent/'source-requests-20261009'
read = lambda path: json.loads(path.read_text(encoding='utf-8-sig'))
write = lambda path, data: path.write_text(json.dumps(data,indent=2,ensure_ascii=False)+'\n',encoding='utf8')

DATA = [
    ('bzip2','bzlib/bzip2','1.0.8-4','bzip2-1.0.8','6a8690fc8d26c815e798c588f796eabe9d684cf0','https://sourceware.org/git/bzip2.git',
     'bzip2 custom BSD-style license; source LICENSE',
     ['No external library dependency declared; compiler/C runtime scope still needs confirmation'],
     'Three candidate patches: cygming ABI/build adjustments, autotools build system, CLI progress reporting'),
    ('fontconfig','fontconfig','2.18.3','2.18.3','0f236723a3c26bd9745e32ba2b3ee21e5f809295','https://gitlab.freedesktop.org/fontconfig/fontconfig.git',
     'Fontconfig permissive custom license; source COPYING',
     ['Expat and FreeType; optional intl/iconv/threads depend on configuration','FreeType recipe adds brotli, bzip2, libpng, zlib and conditional HarfBuzz; actual graph unverified'],
     'Two candidate Windows config installation/path patches; package revision 1 is only a candidate'),
    ('gmp','gmp','6.3.0',None,None,'https://gmplib.org/repo/gmp/',
     'LGPL-3.0-or-later OR GPL-2.0-or-later; source README and COPYING*',
     ['No external library dependency declared; assembly/ABI/CPU and compiler choices need confirmation'],
     'Two candidate static-link/dllimport patches; package revision 2 is only a candidate; upstream Mercurial tags/raw-file/lookup return HTTP 403'),
    ('gnutls','gnutls','3.8.13-3','3.8.13','b390d80208ed60f1b33ad899475951a8efb40ccd','https://gitlab.com/gnutls/gnutls.git',
     'Library LGPL-2.1-or-later, other files GPL-3.0-or-later and documentation GFDL; source README.md',
     ['Nettle/hogweed -> GMP; libtasn1; libidn2 -> libunistring/iconv; intl; winpthread; brotli/zlib/zstd depend on configuration',
      'Candidate static recipe uses --without-p11-kit and --disable-libdane; package depends list is not the static link graph'],
     'Four candidate patches: clang build, external libtasn1 detection, examples, coverage rules'),
    ('libiconv','iconv','1.19-1','v1.19','a8850dc314a906b7bbe49a7c60424c7b10f57236','https://git.savannah.gnu.org/git/libiconv.git',
     'libiconv/libcharset libraries LGPL-2.1-or-later; tool/documentation GPL-3.0-or-later; source README',
     ['libcharset is included in the source; gettext/NLS scope differs for library vs iconv executable'],
     'Three candidate patches: configure CR/awk, pointer cast/buffer, CP65001 UTF-8 alias; generated tables are regenerated by recipe'),
    ('xz','lzma/xz','5.8.4','v5.8.4','d3e650e63c110e830fd5391e7f8b45df0b91d3da','https://github.com/tukaani-project/xz.git',
     'liblzma 0BSD; tools and other files have additional licenses; source COPYING*',
     ['liblzma versus xz command gettext/threads scope needs confirmation'],
     'Candidate recipe 5.8.4-1 declares no patch input; this is not a Gyan no-patch declaration'),
    ('libxml2','libxml2','v2.15.0-126-g31094e5d','v2.15.0','31094e5d0f65a528965e8c32a488e5a7f36118ca','https://github.com/GNOME/libxml2.git',
     'MIT; exact commit Copyright',
     ['Exact source has optional iconv, ICU, threads and zlib; Python/readline are optional tool/binding features','Reported base tag is not the source version: target is 126 commits ahead'],
     'Current MSYS2 recipe 2.15.4-1 is comparison only; its patches are not assigned to the reported Git snapshot'),
    ('zlib-ng','zlib','v1.2.8_jtkv4-2966-g9174ab6','v1.2.8_jtkv4','9174ab6bf58ac9a518dbe197b948c897f74834f5','https://github.com/zlib-ng/zlib-ng.git',
     'Zlib license; exact commit LICENSE.md',
     ['No external runtime library declared; GoogleTest and related options concern tests','ZLIB_COMPAT defaults OFF in this commit; confirm compatibility mode, library naming and routing for FFmpeg/other libraries','Reported base tag is not zlib 1.2.8: target is 2966 commits ahead'],
     'Current MSYS2 recipe 2.3.3-2 and its two naming/CMake patches are comparison only'),
]

if __name__ == '__main__':
    receipts = read(OUT/'upstream-receipts.json')
    archive_receipts = {item['file']:item for item in receipts if item.get('file','') and item['file'].startswith('archives/')}
    patches = read(OUT/'patch-checks.json')
    resolution = []
    for name, inventory_name, version, tag, commit, repo, license_text, deps, patch_note in DATA:
        archive = archive_receipts['archives/'+NAMES[name]]
        assert hashlib.sha256((OUT/archive['file']).read_bytes()).hexdigest()==archive['sha256']
        recipe_text = (OUT/'recipes'/name/'PKGBUILD').read_text(encoding='utf8')
        checksum_match = archive['sha256'] in recipe_text
        for patch in (OUT/'recipes'/name).glob('*'):
            if patch.suffix in ('.patch','.diff'):
                assert hashlib.sha256(patch.read_bytes()).hexdigest() in recipe_text, patch
        directory_receipt = next(item for item in receipts if item.get('file')=='upstream/msys2-'+name+'-directory.json')
        pin = directory_receipt['url'].split('?ref=')[1]
        if name in ('libxml2','zlib-ng'):
            compare = read(OUT/('upstream/'+name+'-compare.json'))
            assert compare['status']=='ahead' and compare['ahead_by']==(126 if name=='libxml2' else 2966)
            assert read(OUT/('upstream/'+name+'-commit.json'))['sha']==commit
        resolution.append(dict(component=name,inventoryName=inventory_name,publisherReportedVersion=version,
                               sourceRepository=repo,vcs='Mercurial' if name=='gmp' else 'Git',tag=tag,
                               fullCommit=commit,revisionStatus='UNRESOLVED: upstream HTTP 403; release source pinned by SHA256' if name=='gmp' else 'UPSTREAM RESOLVED',
                               sourceArchive={key:archive[key] for key in ('file','url','bytes','sha256')},
                               sha256MatchesCandidateRecipe=checksum_match,gpgSignatureVerified=False,
                               candidateRecipeCommit=pin,candidateRecipe='recipes/'+name+'/PKGBUILD',
                               candidateRecipeVersion=re.search(r'^pkgver=(.*)$',recipe_text,re.M).group(1),
                               candidatePackageRevision=re.search(r'^pkgrel=(.*)$',recipe_text,re.M).group(1),
                               patchAudit=patch_note,patchChecks=[item for item in patches['results'] if item['component']==name],
                               licenseEvidence=license_text,dependencyAudit=deps,
                               binaryBindingVerified=False,publisherPatchUsageVerified=False,
                               publisherBuildConfigurationReceived=False,correspondingSourceStatus='BLOCKED'))
    write(OUT/'upstream-resolution.json',dict(schema=1,reviewLocalDate='2026-10-10',timezone='Asia/Bangkok',
          status='BLOCKED / INCOMPLETE',rows=resolution,fullGitCommitsResolved=7,
          releaseSourcesCollected=8,archiveScope='Local ignored source archives; receipts and selected source text are committed evidence, not a complete source distribution'))
    reply = OUT/'gyan-user-provided-email.txt'
    evidence = dict(file='../gyan-response-20261010/'+reply.name,sha256=hashlib.sha256(reply.read_bytes()).hexdigest(),
                    bytes=reply.stat().st_size,type='user-provided email text',providedLocalDate='2026-10-10',timezone='Asia/Bangkok',
                    originalEmailHeadersReceived=False,independentlyAuthenticated=False,responseSentDate=None,
                    whitespaceNormalized=True,transportEscapesRetained=True)
    contact = read(REQUEST_DIR/'contact-verification.json')
    contact.update(schema=3,reviewDate='2026-10-10',status='Gyan RESPONDED — user-provided email text / yt-dlp AWAITING RESPONSE',
                   responseStatus='MIXED: Gyan RESPONDED; yt-dlp AWAITING RESPONSE',responseEvidence=[evidence],
                   statusBasis='User supplied a text attributed to Gyan in this chat on 10 October 2026 (Asia/Bangkok). No original reply headers or independent authentication. yt-dlp remains awaiting response.')
    for item in contact['contacts']:
        if item['publisher']=='Gyan':
            item.update(responseStatus='RESPONDED — user-provided email text',responseEvidence=[evidence],
                        responseIndependentlyVerified=False,followupDraft='../gyan-response-20261010/GYAN-FOLLOWUP-DRAFT.md',
                        followupStatus='DRAFT — NOT SENT')
    contact['mutations']='Working docs/evidence only; binaries, dependencies, archived r2 kit and release manifests unchanged'
    contact['networkScope']='Read-only HTTPS upstream refs/APIs/source archives and candidate MSYS2 recipes. No agent email, contact form or issue submission. Original sending remains user-reported; supplied Gyan reply text has no independent delivery/authentication.'
    write(REQUEST_DIR/'contact-verification.json',contact)
    inventory = read(INVENTORY_DIR/'source-inventory.json')
    inventory['schema']=2
    inventory['publisherResponse']=dict(status='Gyan RESPONDED — user-provided email text',evidence=evidence,
          audit='../gyan-response-20261010/upstream-resolution.json',ytDlpResponseStatus='AWAITING RESPONSE')
    inventory['sourceFiles']=[item for item in inventory['sourceFiles'] if not item['file'].startswith('../gyan-response-20261010/')]
    for item in resolution:
        row = next(row for row in inventory['components'] if row['component']=='FFmpeg external: '+item['inventoryName'])
        row.update(version=item['publisherReportedVersion']+'; upstream '+(item['fullCommit'] or 'GMP 6.3.0 release; Mercurial revision unresolved'),
                   presence='enabled in baseline; version publisher-reported via supplied email text',
                   license='GPLv3 combined binary; '+item['licenseEvidence']+'; actual linkage/notices scope pending',
                   notices='Baseline configure/README + user-provided Gyan reply; follow-up source-text license evidence',
                   buildEvidence='Version assertion received; candidate recipes/patches inspected; original scripts/configuration not received',
                   upstreamResolution=item,
                   missing=['Publisher patch/no-patch declaration and exact build flags/link map still missing',
                            'Candidate MSYS2 recipe/package revisions and dependency versions are not bound to the original Gyan binary',
                            'Confirm source repository and any local changes for the actual input; source archive alone does not close corresponding source'],
                   closure='Verify this upstream candidate against original publisher scripts/configuration/patch set and actual static dependency manifest',
                   sourceArchives=[dict(item['sourceArchive'],file='../gyan-response-20261010/'+item['sourceArchive']['file'],binaryBindingVerified=False)])
        if item['component']=='gmp':
            row['missing'].append('Upstream Mercurial tag/full changeset unresolved (HTTP 403); exact release tarball SHA256 is pinned')
        inventory['sourceFiles'].append(dict(row['sourceArchives'][0],status='UPSTREAM SOURCE FETCHED; BINARY CORRESPONDENCE UNVERIFIED',
                                           sha256MatchesCandidateRecipe=item['sha256MatchesCandidateRecipe']))
    write(INVENTORY_DIR/'source-inventory.json',inventory)
    lines=['# Corresponding source inventory — INCOMPLETE','',
           'Candidate 0.2.2-beta.2 / unsigned. Overall source gate **BLOCKED**. All component gates remain BLOCKED pending original build/link/patch evidence.','',
           '**10 October 2026 follow-up: Gyan RESPONDED — user-provided email text; yt-dlp AWAITING RESPONSE.** The eight version gaps are now publisher-reported versions. Seven full Git commits and eight source archives were found; GMP Mercurial revision remains unresolved. Candidate package recipes do not prove original binary inputs. See [audit and remaining gaps](../gyan-response-20261010/README.md).','',
           'This is the working inventory. The archived r2 inventory/source kit remains historical and unchanged. The old make-source-inventory.py writes into archived r2; do not rerun it for this follow-up. apply-response.py applies this evidence overlay to the working inventory only.','',
           'Binary identities and original ZIP binding remain in source-inventory.json and prior receipts. The current mutable publisher download is not the baseline.','',
           '| Component | Version / identity | License / notices scope | Sources | Missing / closure |','| --- | --- | --- | --- | --- |']
    for row in inventory['components']:
        archives='<br>'.join('`'+item['file']+'` SHA `'+item['sha256']+'`' for item in row['sourceArchives']) or 'NOT COLLECTED / not identified'
        values=[row['component'],row['version']+'; '+row['presence'],row['license']+'; '+row['notices'],archives,'BLOCKED: '+'; '.join(row['missing'])+'. '+row['closure']]
        lines.append('| '+' | '.join(value.replace('|','/').replace('\n',' ') for value in values)+' |')
    lines+=['','## Source files / publisher provenance','','The eight follow-up archives are local ignored downloads, with committed receipts and source-text excerpts. Their hashes match candidate recipes for the six release versions; Git snapshot hashes for libxml2/zlib-ng are locally computed. GPG signatures were not verified. This is not a complete corresponding-source delivery.','',
            '| File | Publisher / URL | Bytes | SHA256 |','| --- | --- | ---: | --- |']
    for item in inventory['sourceFiles']:
        lines.append(f"| `{item['file']}` | {item['url']} | {item['bytes']} | `{item['sha256']}` |")
    (INVENTORY_DIR/'SOURCE-INVENTORY.md').write_text('\n'.join(lines)+'\n',encoding='utf8')
    write(OUT/'response-coverage.json',dict(responseEvidence=evidence,claimScope='Version assertions and official-repo/mirror statement; scripts described as custom/non-portable but not supplied',
          F1='PARTIAL: eight version strings supplied; original repo selection and patches/no-patches not confirmed',
          F2='OPEN: original scripts/configuration/linkage not supplied; non-portability is not an explicit refusal to supply',
          F3='PARTIAL: three package-style revisions given; original UCRT/toolchain/package/source snapshot unconfirmed',
          F4='OPEN: actual transitive static graph unconfirmed',F5='OPEN: complete source delivery not supplied',
          ytDlpResponseStatus='AWAITING RESPONSE',followupStatus='DRAFT — NOT SENT',sourceGate='BLOCKED / INCOMPLETE'))
    print('Updated working inventory: 8 rows, 7 Git commits, 8 source archives; all gates BLOCKED; yt-dlp awaiting')
